package dailyassignments;

public class DailyAssignment1_TypeCasting {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		/*Create a Java program that:
			1.Stores 10.75 in a double variable. 
			2.Explicitly typecasts it to an int variable. 
			3.Prints both values.*/
		
		
		double mark1 =10.75;
		int mark2 = (int)mark1;
		/*System.out.println("original mark:" +mark1);
        System.out.println("explicit typecase:" + mark2);*/
		
		System.out.println("original mark:" +mark1 +"\nexplicit typecase:" + mark2);
		
		
	}

}
